/* ============================================================
   HEADINGS - owner decision 2026-08-27 (#1190 D1): PARTIAL REVERSAL of #438.
   Big card title ONLY on cards that NAME a sub-game. The semantic marker is
   structural, measured on the corpus: those cards carry >= 4 h2 and zero h3
   (name + Materiel/Resume du jeu/Installation) - no other card has 4 h2.
   The cover keeps its own title rules ([class~=1]).
   NOTHING is promoted by position anymore: an unguarded h2:first-child
   selector is the #1190 D1 defect and must not come back.
   Every heading below the card title is a BANNER, two weights, one family:
   h2 = section banner (larger), h3 = numbered-step banner (smaller).
   Index-independence for LEVELS (no per-index nth-of-type) is kept.
   ============================================================ */

/* Card main title: ONLY the sub-game name on the four variant cards.
   card:has(h2 ~ h2 ~ h2 ~ h2) matches a card whose 4th h2 exists - the
   measured structural marker of the sub-game cards; :first-child then
   picks their first h2 (the game name). Not a card index, not position
   alone: the guard is the deck's own structure. */
card:has(h2 ~ h2 ~ h2 ~ h2) h2:first-child {
    font-size: 1.3em;
    font-style: normal;
    text-transform: uppercase;
    font-weight: bold;
    line-height: 1.05;
    background-color: transparent;
    padding: 0;
    border-bottom: none;
    margin-top: 0; margin-bottom: 0.12em;
}

/* Section banners (Materiel, Resume du jeu, Variantes, Fin de partie...):
   colored banner keyed to the sub-game color, LARGER than the h3 step
   banner - two weights, one visual family (owner decision 2026-08-27). */
card:not([class~="1"]) h2 {
    font-size: 0.85em;
    font-weight: bold;
    text-transform: uppercase;
    background-color: var(--color-background, var(--color-group-bg, #ddd));
    padding: 0.26em 0.45em;
    border-bottom: 0.2em solid var(--color-box, var(--color-group-box, #888));
    margin-top: 0.18em;
    margin-bottom: 0.04em;
}

/* Numbered steps: colored banner. The «1.», «2.» number is already in the
   heading text, so no separate (previously broken/empty) number box. */
card:not([class~="1"]) h3 {
    font-size: 0.7em;
    background-color: var(--color-background, var(--color-group-bg, #ddd));
    padding: 0.22em 0.4em;
    font-weight: bold;
    border-bottom: 0.2em solid var(--color-box, var(--color-group-box, #888));
    text-transform: uppercase;
    margin-top: 0.08em; margin-bottom: 0.06em;
}

